<div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><div class="text-muted small"><?=e($client['company_name'])?></div><h1 class="h3 mb-1">Assessment findings</h1><div class="text-muted"><?=e($assessment['title'])?></div></div><a class="btn btn-primary" href="<?=url('findings/create',['assessment_id'=>(int)$assessment['id']])?>">New finding</a></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Finding</th><th>Severity</th><th>Risk</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($findings as $f):?><tr><td><div class="fw-semibold"><?=e($f['title'])?></div><small class="text-muted"><?=e($f['recommendation']??'')?></small></td><td><?=e(ucfirst($f['severity']))?></td><td><?=((int)$f['likelihood'])*((int)$f['impact'])?>/25</td><td><?=e(ucfirst($f['status']))?></td><td><form method="post" action="<?=url('findings/status',['assessment_id'=>(int)$assessment['id']])?>" class="d-flex gap-1"><?php include __DIR__.'/../partials/csrf.php';?><input type="hidden" name="id" value="<?=(int)$f['id']?>"><select name="status" class="form-select form-select-sm"><option value="open">Open</option><option value="accepted">Accepted</option><option value="mitigated">Mitigated</option><option value="closed">Closed</option></select><button class="btn btn-sm btn-outline-primary">Update</button></form></td></tr><?php endforeach;?><?php if(!$findings):?><tr><td colspan="5" class="text-center text-muted py-5">No findings recorded.</td></tr><?php endif;?></tbody></table></div></div></div>
